      "The source's repeated teaching framework is paraphrased once in commonSections. Every numbered module retains its own progressive drill, transfer drill, proof task and four diagnostic questions, with physical-page provenance.",
      "Source working assumptions about market fit and ramp length are not independently verified market statistics or income guarantees. A one-week or one-month ramp is a classification hypothesis, not a delivery promise.",
